// ============================================================
// CampaignDetailPanel — signals breakdown + pre-generated reasoning
// ------------------------------------------------------------
// Signals trace to the row (null ROAS → "—", never 0). "Lumi's Read" is
// pre-generated by the sweep: it loads on expand (GET, no click), shows an
// honest "after the next sweep" when absent, flags an aged row "may be stale",
// and serves a cached read with no second request on re-expand.
// ============================================================
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen, waitFor, act, fireEvent } from '@testing-library/react';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { CampaignDetailPanel } from './CampaignDetailPanel.jsx';

// Mock the shared client via a hoisted handle — feature code (and its tests) must
// not import '@/lib/api' directly (arch-check). We reference the mock fn instead.
const { get } = vi.hoisted(() => ({ get: vi.fn() }));
vi.mock('@/lib/api.js', () => ({ api: { get } }));

const campaign = (over = {}) => ({
  entityId: 'd1', name: 'Eid Sale', channel: 'META', objective: 'OUTCOME_SALES',
  spendMinor: 50000, ctr: 0.0523, frequency: 2.04, roas: null, currency: 'EGP', ...over,
});
const READING = 'Healthy engagement but no revenue tracked. Verify your lead form setup.';

beforeEach(() => {
  vi.clearAllMocks();
  get.mockResolvedValue({ data: { reasoning: null, stale: false, generatedAt: null } });
});

describe('CampaignDetailPanel — signals', () => {
  it('renders real signals; null ROAS is "—", never a fabricated 0', () => {
    render(<CampaignDetailPanel campaign={campaign({ entityId: 'sig1' })} verdict="WATCH" impact={6} />);
    expect(screen.getByText('WATCH')).toBeInTheDocument();
    expect(screen.getByText('6/10')).toBeInTheDocument();
    expect(screen.getByText('5.23%')).toBeInTheDocument();  // 0.0523 fraction → 5.23%
    expect(screen.getByText('2.04')).toBeInTheDocument();   // frequency
    expect(screen.getByText('OUTCOME_SALES')).toBeInTheDocument();
    expect(screen.getAllByTitle('No data').length).toBeGreaterThan(0); // roas is null → em-dash
  });
});

describe("CampaignDetailPanel — Lumi's Read (pre-generated)", () => {
  it('shows the pre-generated reasoning immediately on expand — no button, no click', async () => {
    get.mockResolvedValue({ data: { reasoning: READING, stale: false, generatedAt: new Date().toISOString() } });
    render(<CampaignDetailPanel campaign={campaign({ entityId: 'read1' })} verdict="WATCH" impact={6} />);

    await waitFor(() => expect(screen.getByText(READING)).toBeInTheDocument());
    expect(get).toHaveBeenCalledWith('/api/lumi/entities/read1/reasoning');
    expect(screen.getByText(/updated/i)).toBeInTheDocument();
    expect(screen.queryByText(/get lumi's read/i)).not.toBeInTheDocument(); // no on-demand button
  });

  it('shows an honest "after the next sweep" when nothing is generated yet', async () => {
    get.mockResolvedValue({ data: { reasoning: null, stale: false, generatedAt: null } });
    render(<CampaignDetailPanel campaign={campaign({ entityId: 'null1' })} verdict="HOLD" impact={4} />);
    await waitFor(() => expect(screen.getByText(/after the next sweep/i)).toBeInTheDocument());
  });

  it('flags an aged row as "may be stale"', async () => {
    get.mockResolvedValue({ data: { reasoning: READING, stale: true, generatedAt: new Date(Date.now() - 26 * 3600 * 1000).toISOString() } });
    render(<CampaignDetailPanel campaign={campaign({ entityId: 'stale1' })} verdict="KILL" impact={9} />);
    await waitFor(() => expect(screen.getByText(READING)).toBeInTheDocument());
    expect(screen.getByText(/may be stale/i)).toBeInTheDocument();
  });

  it('shows an honest error state when the read fails', async () => {
    get.mockRejectedValue(new Error('500'));
    render(<CampaignDetailPanel campaign={campaign({ entityId: 'err1' })} verdict="KILL" impact={9} />);
    await waitFor(() => expect(screen.getByText(/couldn.t load reasoning/i)).toBeInTheDocument());
  });

  // Counts the REASONING requests specifically. The panel also fetches its
  // learning track record on mount, and that one is deliberately not cached —
  // a total-call count would conflate the two.
  it('serves a cached read on re-expand — no second request', async () => {
    get.mockResolvedValue({ data: { reasoning: READING, stale: false, generatedAt: new Date().toISOString() } });
    const c = campaign({ entityId: 'cache1' });
    const reasoningCalls = () => get.mock.calls.filter(([url]) => !String(url).includes('/learning')).length;

    const { unmount } = render(<CampaignDetailPanel campaign={c} verdict="HOLD" impact={4} />);
    await waitFor(() => expect(screen.getByText(READING)).toBeInTheDocument());
    expect(reasoningCalls()).toBe(1);
    unmount();

    render(<CampaignDetailPanel campaign={c} verdict="HOLD" impact={4} />);
    await waitFor(() => expect(screen.getByText(READING)).toBeInTheDocument());
    expect(reasoningCalls()).toBe(1); // served from the session cache
  });
});

// ── Actions on a decision ────────────────────────────────────
// Lumi initiates, the human acts. Neither control touches the ad platform: Copy
// hands over the decision verbatim, the link opens the platform's own UI.
// NOTE: fireEvent, not userEvent — userEvent.setup() installs its OWN
// navigator.clipboard stub, which silently replaces the mock these tests assert.
describe('CampaignDetailPanel — ActionBar', () => {
  const writeText = vi.fn(() => Promise.resolve());

  beforeEach(() => {
    writeText.mockClear();
    writeText.mockResolvedValue(undefined);
    Object.defineProperty(navigator, 'clipboard', { value: { writeText }, configurable: true, writable: true });
  });

  it('offers actions on a KILL', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" rationale="ROAS 0.42 below break-even." confidence={0.9} />);
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
  });

  it('offers actions on a SCALE', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="SCALE" />);
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
  });

  // REALLOCATE is a real emitted verdict (verdictEngine's INEFFICIENT_SCALING
  // and AUDIENCE_MISMATCH branches, plus AllocationService) and it asks for an
  // intervention. It sat in this "no bar" list only because nextActionFor had
  // no entry for it — which also cost it its decision lifecycle, below.
  it('offers actions on a REALLOCATE', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="REALLOCATE" />);
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
  });

  // REFRESH is the engine's most common creative verdict (both fatigue branches
  // plus LOW_CTR) and it has a real execution capability behind it —
  // REFRESH_CREATIVE, wired through to Meta. It sat in the "no bar" list for the
  // same reason REALLOCATE did: nextActionFor had no entry for it.
  it('offers actions on a REFRESH', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="REFRESH" />);
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
  });

  it('tells a REFRESH to change the ad, not to move or add budget', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="REFRESH" />);
    expect(screen.getByText(/Refresh the creative/)).toBeInTheDocument();
    // The money is not the problem on a REFRESH — the ad is worn out.
    expect(screen.queryByText(/Move spend to stronger campaigns/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Increase budget or expand audience/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Pause and reallocate budget/)).not.toBeInTheDocument();
  });

  // Nothing to act on → no bar. An action button under a "keep running" verdict
  // would invent an ask the engine never made.
  it.each(['HOLD', 'WATCH', null])('renders no action bar for %s', (verdict) => {
    render(<CampaignDetailPanel campaign={campaign()} verdict={verdict} />);
    expect(screen.queryByText('Copy decision')).not.toBeInTheDocument();
    expect(screen.queryByText(/open in/i)).not.toBeInTheDocument();
  });

  it('copies the decision as the same text the panel shows', async () => {
    render(
      <CampaignDetailPanel
        campaign={campaign()}
        verdict="KILL"
        rationale="Lowest CTR in the conversion group (0.85% vs 1.42% group average) — weakest engagement."
        confidence={0.6}
      />,
    );

    await act(async () => { fireEvent.click(screen.getByText('Copy decision')); });

    const text = writeText.mock.calls[0][0];
    expect(text).toContain('Campaign: Eid Sale');
    expect(text).toContain('Verdict: KILL');
    expect(text).toContain('Pause and reallocate budget');
    expect(text).toContain('Lowest CTR in the conversion group (0.85% vs 1.42% group average)');
    expect(text).toContain('Confidence: Medium');
    expect(await screen.findByText('Copied')).toBeInTheDocument();
  });

  // The one outcome worse than no copy button: reporting success when nothing
  // reached the clipboard, so the marketer pastes stale content.
  it('says so when the copy FAILS — never a silent or false "Copied"', async () => {
    writeText.mockRejectedValue(new Error('Permission denied'));
    render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" />);

    fireEvent.click(screen.getByText('Copy decision'));

    expect(await screen.findByText(/couldn.t copy/i)).toBeInTheDocument();
    expect(screen.queryByText('Copied')).not.toBeInTheDocument();
  });

  it('returns to rest after the feedback window', async () => {
    vi.useFakeTimers();
    render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" />);

    await act(async () => { fireEvent.click(screen.getByText('Copy decision')); });
    expect(screen.getByText('Copied')).toBeInTheDocument();

    await act(async () => { await vi.advanceTimersByTimeAsync(2000); });

    expect(screen.queryByText('Copied')).not.toBeInTheDocument();
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
    vi.useRealTimers();
  });

  it('links to the campaign in the platform when it carries a platform id', () => {
    render(<CampaignDetailPanel campaign={campaign({ externalId: '120210987654321' })} verdict="KILL" />);
    const link = screen.getByRole('link', { name: /open in META/i });
    expect(link).toHaveAttribute('href', expect.stringContaining('selected_campaign_ids=120210987654321'));
    expect(link).toHaveAttribute('rel', 'noopener noreferrer');
  });

  it('renders NO link when the row carries no platform id (never a generic account URL)', () => {
    render(<CampaignDetailPanel campaign={campaign({ externalId: null })} verdict="KILL" />);
    expect(screen.queryByRole('link')).not.toBeInTheDocument();
    expect(screen.getByText('Copy decision')).toBeInTheDocument(); // copy still works
  });

  it('renders no link for a channel with no verified campaign deep-link', () => {
    render(<CampaignDetailPanel campaign={campaign({ channel: 'TIKTOK', externalId: '12345' })} verdict="KILL" />);
    expect(screen.queryByRole('link')).not.toBeInTheDocument();
  });

  it('sits below the "Next step" line, inside the Why block', () => {
    const { container } = render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" rationale="ROAS 0.42 below break-even." />);
    const whyBlock = screen.getByText(/Why kill\?/i).closest('.rounded-xl');
    expect(whyBlock).toContainElement(screen.getByText('Copy decision'));
    // Ordering: the recommendation is stated before it can be acted on.
    const html = container.innerHTML;
    expect(html.indexOf('Next step:')).toBeLessThan(html.indexOf('Copy decision'));
  });
});

// ── Did you act on this? ─────────────────────────────────────
// The one write in the product whose entire purpose is to be believed, and it
// now sits on the DECISION rather than under the ad-set evidence. What these
// pin is that the evidence is not a precondition: a KILL is answerable the
// moment it is explained, with no ranking, no ad sets and no second request.
describe('CampaignDetailPanel — decision lifecycle', () => {
  const onExecute = vi.fn();
  const onDismiss = vi.fn();
  const withActions = (props = {}) => render(
    <CampaignDetailPanel
      campaign={campaign()} verdict="KILL"
      onExecute={onExecute} onDismiss={onDismiss}
      {...props}
    />,
  );

  beforeEach(() => { onExecute.mockClear(); onDismiss.mockClear(); });

  it('asks the question on an actionable verdict', () => {
    withActions();
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Not applicable' })).toBeInTheDocument();
    expect(screen.getByText(/Either answer is recorded/)).toBeInTheDocument();
  });

  // The whole point of the move. This panel receives no evidence prop, has no
  // ranking behind it, and never asks for one.
  it('needs no evidence, no ranking and no ad sets to ask it', () => {
    const { container } = withActions();
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(container.textContent).not.toMatch(/Where to execute/);
  });

  it('asks it on a SCALE too', () => {
    withActions({ verdict: 'SCALE' });
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
  });

  // Same gate as the utility actions beside it — deliberately not broadened. A
  // verdict with nothing to act on has nothing to have acted on.
  it.each(['HOLD', 'WATCH', null])('does not ask under %s', (verdict) => {
    withActions({ verdict });
    expect(screen.queryByRole('button', { name: 'I executed this' })).not.toBeInTheDocument();
  });

  // THE GAP THIS CLOSES, now inverted. When the lifecycle moved onto this panel
  // it started gating on nextActionFor, which had no REALLOCATE entry — so the
  // one verdict whose entire content is "move the money" lost every way to
  // record that anyone did. Nothing failed; the buttons were simply absent.
  it('REALLOCATE exposes decision lifecycle actions', () => {
    withActions({ verdict: 'REALLOCATE' });
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Not applicable' })).toBeInTheDocument();
  });

  // The gap this PR closes. `intentAt` is stamped ONLY from inside this
  // ActionBar, and decisionLearning filters on `intentAt: { not: null }` — so
  // while REFRESH had no next action, no REFRESH decision could ever be recorded
  // as acted on, and the verdict could not reach the learning population at all.
  // The capability existed the whole time; the bridge did not.
  it('REFRESH exposes decision lifecycle actions', () => {
    withActions({ verdict: 'REFRESH' });
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Not applicable' })).toBeInTheDocument();
  });

  it('REFRESH needs no evidence to be answerable', () => {
    const { container } = withActions({ verdict: 'REFRESH' });
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(container.textContent).not.toMatch(/Where to execute/);
  });

  // The same invariant as KILL's, restated for the verdict that regressed: this
  // render passes no evidence, no ranking and no ad sets.
  it('REALLOCATE needs no evidence to be answerable', () => {
    const { container } = withActions({ verdict: 'REALLOCATE' });
    expect(screen.getByRole('button', { name: 'I executed this' })).toBeInTheDocument();
    expect(container.textContent).not.toMatch(/Where to execute/);
  });

  it('tells a REALLOCATE to move spend, not to scale or to pause', () => {
    withActions({ verdict: 'REALLOCATE' });
    // Shared lifecycle mechanism, distinct next step: SCALE puts MORE behind a
    // winner, REALLOCATE moves what this has ELSEWHERE, KILL pauses first.
    expect(screen.getByText(/Move spend to stronger campaigns/)).toBeInTheDocument();
    expect(screen.queryByText(/Increase budget or expand audience/)).not.toBeInTheDocument();
    expect(screen.queryByText(/Pause and reallocate budget/)).not.toBeInTheDocument();
  });

  // The complete lifecycle action contract, in one place.
  it.each([
    ['KILL', true], ['SCALE', true], ['REALLOCATE', true], ['REFRESH', true],
    ['HOLD', false], ['WATCH', false],
  ])('%s → action surface: %s', (verdict, expected) => {
    withActions({ verdict });
    const asked = screen.queryByRole('button', { name: 'I executed this' }) !== null;
    expect(asked).toBe(expected);
  });

  // The fix belongs in the actionability layer. A verdict name in the renderer
  // would mean the next verdict that needs a lifecycle gets fixed in two places
  // — and the second one gets forgotten, which is how this regression happened.
  it('carries no REALLOCATE branch of its own', () => {
    const src = readFileSync(
      path.resolve(path.dirname(fileURLToPath(import.meta.url)), 'CampaignDetailPanel.jsx'),
      'utf8',
    );
    expect(src).not.toMatch(/REALLOCATE/);
  });

  it('stays silent when the host passes no callbacks', () => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" />);
    expect(screen.queryByRole('button', { name: 'I executed this' })).not.toBeInTheDocument();
    // …while the utility actions, which need no host, are still there.
    expect(screen.getByText('Copy decision')).toBeInTheDocument();
  });

  it.each([
    [{ onExecute }, 'only an execute handler'],
    [{ onDismiss }, 'only a dismiss handler'],
  ])('asks nothing given %s — half a question is not a question', (props) => {
    render(<CampaignDetailPanel campaign={campaign()} verdict="KILL" {...props} />);
    expect(screen.queryByRole('button', { name: 'I executed this' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Not applicable' })).not.toBeInTheDocument();
  });

  it('calls execute exactly once, with no arguments of its own', () => {
    withActions();
    fireEvent.click(screen.getByRole('button', { name: 'I executed this' }));
    expect(onExecute).toHaveBeenCalledTimes(1);
    expect(onDismiss).not.toHaveBeenCalled();
  });

  it('calls dismiss exactly once', () => {
    withActions();
    fireEvent.click(screen.getByRole('button', { name: 'Not applicable' }));
    expect(onDismiss).toHaveBeenCalledTimes(1);
    expect(onExecute).not.toHaveBeenCalled();
  });

  it.each([
    ['executing',  'Recording…'],
    ['dismissing', 'Recording…'],
    ['executed',   'Recorded as executed'],
    ['dismissed',  'Recorded as not applicable'],
    ['stale',      'This verdict was replaced — refresh to see the current one'],
    ['error',      "Couldn't record — refresh and try again"],
  ])('%s reads "%s"', (executionState, sentence) => {
    withActions({ executionState });
    expect(screen.getByText(sentence)).toBeInTheDocument();
  });

  // A data-quality state says we have not judged this campaign yet. Collecting
  // "I executed this" against a call nobody made would seed the learning loop
  // with an answer to a question never asked.
  it('asks nothing when the verdict is a data-quality state', () => {
    withActions({ verdict: 'WATCH', rootCause: 'INSUFFICIENT_DATA' });
    expect(screen.queryByRole('button', { name: 'I executed this' })).not.toBeInTheDocument();
  });

  it('sits last — after Next step and after the utility actions', () => {
    const { container } = withActions({ rationale: 'ROAS 0.42 below break-even.' });
    const html = container.innerHTML;
    // The reader should understand the decision before being asked whether they
    // acted on it: a claim collected above its own evidence is a claim about
    // something the operator has not read yet.
    expect(html.indexOf('Next step:')).toBeLessThan(html.indexOf('Copy decision'));
    expect(html.indexOf('Copy decision')).toBeLessThan(html.indexOf('Did you act on this?'));
  });

  it('stays inside the Why block, with the rest of the decision', () => {
    withActions({ rationale: 'ROAS 0.42 below break-even.' });
    const whyBlock = screen.getByText(/Why kill\?/i).closest('.rounded-xl');
    expect(whyBlock).toContainElement(screen.getByRole('button', { name: 'I executed this' }));
  });
});
